import { computed, ref, watch, onMounted } from "vue";
import { useDealStore } from "../stores/dealStore";

const store = useDealStore();

const animated = ref({
  numDoors: 0,
  totalValue: 0,
  totalDebt: 0,
  equity: 0,
});

const hasDeals = computed(() => store.portfolioStats.numDoors > 0);

function animateTo(
  key: keyof typeof animated.value,
  target: number,
  duration = 800
) {
  const start = animated.value[key];
  const diff = target - start;
  if (diff === 0) return;
  const startTime = performance.now();
  const step = (now: number) => {
    const elapsed = now - startTime;
    const progress = Math.min(elapsed / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    animated.value[key] = start + diff * eased;
    if (progress < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

function syncAnimations() {
  const stats = store.portfolioStats;
  animateTo("numDoors", stats.numDoors, 600);
  animateTo("totalValue", stats.totalValue, 900);
  animateTo("totalDebt", stats.totalDebt, 900);
  animateTo("equity", stats.equity, 1000);
}

watch(() => store.portfolioStats, syncAnimations, { deep: true });

onMounted(() => {
  const stats = store.portfolioStats;
  animated.value = { ...stats };
});

function formatMoney(val: number): string {
  const abs = Math.abs(val);
  if (abs >= 1_000_000) {
    return `$${(val / 1_000_000).toFixed(abs >= 10_000_000 ? 1 : 2)}M`;
  }
  if (abs >= 1_000) {
    return `$${(val / 1_000).toFixed(abs >= 100_000 ? 0 : 1)}K`;
  }
  return `$${Math.round(val).toLocaleString()}`;
}

/*--script--*/

src/components/SendOfferModal.vue.content:
import { ref } from 'vue';
import api from '../api';
import MoneyInput from './ui/MoneyInput.vue';

defineProps<{
  isOpen: boolean;
}>();

const emit = defineEmits(['close']);

const form = ref({
  agent_name: '',
  agent_email: '',
  property_address: '',
  purchase_price: 0,
  inspection_period_days: 0
});

const loading = ref(false);
const message = ref<{ type: 'success' | 'error'; text: string } | null>(null);

const closeModal = () => {
  message.value = null;
  // Reset form only if successful or if user wants to clear? 
  // Maybe better to keep inputs if cancelled accidentally.
  emit('close');
};

const sendOffer = async () => {
  if (!form.value.agent_name || !form.value.agent_email || !form.value.property_address || !form.value.purchase_price) {
     message.value = { type: 'error', text: 'Please fill in all required fields.' };
     return;
  }

  loading.value = true;
  message.value = null;

  try {
    const res = await api.sendOffer({
        agent_name: form.value.agent_name,
        agent_email: form.value.agent_email,
        property_address: form.value.property_address,
        purchase_price: form.value.purchase_price,
        inspection_period_days: form.value.inspection_period_days
    });

    if (res.success) {
      message.value = { type: 'success', text: 'Offer sent successfully!' };
      setTimeout(() => {
          closeModal();
          // Reset form after success
          form.value = {
            agent_name: '',
            agent_email: '',
            property_address: '',
            purchase_price: 0,
            inspection_period_days: 0
          };
      }, 1500);
    } else {
      message.value = { type: 'error', text: res.message || 'Failed to send offer.' };
    }
  } catch (error: any) {
    message.value = { type: 'error', text: error.response?.data?.detail || 'An unexpected error occurred.' };
  } finally {
    loading.value = false;
  }
};

/*--script--*/

