src/components/liquidity/TimelineChart.v.content:
import { ref, onMounted, onUnmounted, watch, computed } from 'vue'
import type { DayBucket } from '../../types/liquidity'
import { todayISO } from '../../utils/liquidityEngine'

const props = defineProps<{
  days: DayBucket[]
  globalMin: number
  globalMinDates: string[]
  firstNegativeDate: string | null
}>()

const emit = defineEmits<{
  (e: 'selectDay', date: string): void
}>()

const canvasRef = ref<HTMLCanvasElement | null>(null)
const containerRef = ref<HTMLDivElement | null>(null)

const DAY_WIDTH = 48
const CHART_PADDING_TOP = 40
const CHART_PADDING_BOTTOM = 52
const CHART_PADDING_LEFT = 72
const CHART_PADDING_RIGHT = 24

const hoveredIndex = ref<number | null>(null)
const selectedIndex = ref<number | null>(null)
const scrollX = ref(0)
const isDragging = ref(false)
let dragStartX = 0
let dragStartScroll = 0
let velocityX = 0
let lastDragX = 0
let lastDragTime = 0
let animFrame = 0

const today = todayISO()
const MONTH_NAMES = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
const WEEKDAY_NAMES = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']

const totalWidth = computed(() => props.days.length * DAY_WIDTH + CHART_PADDING_LEFT + CHART_PADDING_RIGHT)

const activeDay = computed<DayBucket | null>(() => {
  const idx = hoveredIndex.value ?? selectedIndex.value
  if (idx === null || idx < 0 || idx >= props.days.length) return null
  return props.days[idx] ?? null
})

const balanceRange = computed(() => {
  if (props.days.length === 0) return { min: 0, max: 100 }
  let min = Infinity, max = -Infinity
  for (const d of props.days) {
    if (d.balance_k < min) min = d.balance_k
    if (d.balance_k > max) max = d.balance_k
  }
  const pad = Math.max((max - min) * 0.12, 5)
  return { min: Math.min(min - pad, 0), max: max + pad }
})

function yForBalance(b: number, h: number): number {
  const { min, max } = balanceRange.value
  const range = max - min || 1
  const plotH = h - CHART_PADDING_TOP - CHART_PADDING_BOTTOM
  return CHART_PADDING_TOP + plotH * (1 - (b - min) / range)
}

function xForIndex(i: number): number {
  return CHART_PADDING_LEFT + i * DAY_WIDTH + DAY_WIDTH / 2 - scrollX.value
}

function indexForClientX(clientX: number): number | null {
  if (!containerRef.value) return null
  const rect = containerRef.value.getBoundingClientRect()
  const x = clientX - rect.left + scrollX.value - CHART_PADDING_LEFT
  const idx = Math.floor(x / DAY_WIDTH)
  if (idx < 0 || idx >= props.days.length) return null
  return idx
}

function parseDateParts(iso: string): [string, string, string] {
  const parts = iso.split('-')
  return [parts[0] ?? '', parts[1] ?? '', parts[2] ?? '']
}

function weekday(iso: string): number {
  return new Date(iso + 'T00:00:00').getDay()
}

function draw() {
  const canvas = canvasRef.value
  if (!canvas) return
  const container = containerRef.value
  if (!container) return

  const dpr = window.devicePixelRatio || 1
  const w = container.clientWidth
  const h = container.clientHeight
  canvas.width = w * dpr
  canvas.height = h * dpr
  canvas.style.width = w + 'px'
  canvas.style.height = h + 'px'

  const ctx = canvas.getContext('2d')!
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)

  ctx.fillStyle = '#0f1117'
  ctx.fillRect(0, 0, w, h)

  const days = props.days
  if (days.length === 0) return

  const { min, max } = balanceRange.value
  const plotH = h - CHART_PADDING_TOP - CHART_PADDING_BOTTOM

  // Horizontal grid lines + Y labels
  const gridSteps = niceGridSteps(min, max, 6)
  ctx.strokeStyle = '#1e2030'
  ctx.lineWidth = 1
  ctx.font = '11px "JetBrains Mono", "SF Mono", "Fira Code", monospace'
  ctx.textAlign = 'right'
  ctx.textBaseline = 'middle'

  for (const val of gridSteps) {
    const y = yForBalance(val, h)
    if (y < CHART_PADDING_TOP - 5 || y > h - CHART_PADDING_BOTTOM + 5) continue
    ctx.beginPath()
    ctx.moveTo(CHART_PADDING_LEFT, y)
    ctx.lineTo(w, y)
    ctx.stroke()
    ctx.fillStyle = '#5c6078'
    ctx.fillText(formatK(val), CHART_PADDING_LEFT - 8, y)
  }

  // Zero line — solid red, always visible
  const zeroY = yForBalance(0, h)
  const zeroVisible = zeroY >= CHART_PADDING_TOP && zeroY <= h - CHART_PADDING_BOTTOM

  // Negative region fill (drawn before bars so it sits behind)
  if (min < 0 && zeroVisible) {
    const negBottom = Math.min(yForBalance(min, h), h - CHART_PADDING_BOTTOM)
    const negTop = Math.max(zeroY, CHART_PADDING_TOP)
    ctx.fillStyle = 'rgba(239, 68, 68, 0.04)'
    ctx.fillRect(CHART_PADDING_LEFT, negTop, w - CHART_PADDING_LEFT, negBottom - negTop)
  }

  // Visible range
  const firstVisible = Math.max(0, Math.floor((scrollX.value - CHART_PADDING_LEFT) / DAY_WIDTH))
  const lastVisible = Math.min(days.length - 1, firstVisible + Math.ceil(w / DAY_WIDTH) + 2)
  const hIdx = hoveredIndex.value ?? selectedIndex.value

  // --- Day columns: vertical grid lines + labels for EVERY day ---
  ctx.textAlign = 'center'
  ctx.textBaseline = 'top'

  let prevMonth = ''
  for (let i = firstVisible; i <= lastVisible; i++) {
    const x = xForIndex(i)
    if (x < CHART_PADDING_LEFT - DAY_WIDTH || x > w + DAY_WIDTH) continue
    const d = days[i]!
    const [yr, mo, dy] = parseDateParts(d.date)
    const dayNum = parseInt(dy)
    const monthKey = yr + '-' + mo
    const wd = weekday(d.date)
    const isWeekend = wd === 0 || wd === 6
    const isHovered = i === hIdx
    const isToday = d.date === today
    const isFirstOfMonth = dayNum === 1
    const hasTxns = d.net_k !== 0

    // Weekend shading
    if (isWeekend) {
      ctx.fillStyle = 'rgba(255,255,255,0.015)'
      ctx.fillRect(x - DAY_WIDTH / 2, CHART_PADDING_TOP, DAY_WIDTH, plotH)
    }

    // Hovered column highlight
    if (isHovered) {
      ctx.fillStyle = 'rgba(99, 102, 241, 0.08)'
      ctx.fillRect(x - DAY_WIDTH / 2, CHART_PADDING_TOP, DAY_WIDTH, plotH)
    }

    // Vertical grid line per day
    ctx.strokeStyle = isFirstOfMonth ? '#2a2f45' : '#16192a'
    ctx.lineWidth = isFirstOfMonth ? 1 : 0.5
    ctx.beginPath()
    ctx.moveTo(x - DAY_WIDTH / 2, CHART_PADDING_TOP)
    ctx.lineTo(x - DAY_WIDTH / 2, h - CHART_PADDING_BOTTOM)
    ctx.stroke()

    // Month label row (drawn once per new month)
    if (monthKey !== prevMonth) {
      const mIdx = parseInt(mo) - 1
      ctx.fillStyle = '#7c82a0'
      ctx.font = 'bold 10px "JetBrains Mono", monospace'
      ctx.fillText((MONTH_NAMES[mIdx] ?? '') + ' \'' + yr.slice(2), x + 30, h - CHART_PADDING_BOTTOM + 28)
      prevMonth = monthKey
    }

    // Day number label for every day
    ctx.fillStyle = isToday ? '#818cf8' : isHovered ? '#c7d2fe' : hasTxns ? '#94a3b8' : '#3e4460'
    ctx.font = (isToday || isHovered ? 'bold ' : '') + '10px "JetBrains Mono", monospace'
    ctx.fillText(String(dayNum), x, h - CHART_PADDING_BOTTOM + 6)

    // Weekday abbreviation under the number
    ctx.fillStyle = isToday ? '#6366f1' : '#2e3350'
    ctx.font = '8px "JetBrains Mono", monospace'
    ctx.fillText(WEEKDAY_NAMES[wd] ?? '', x, h - CHART_PADDING_BOTTOM + 18)

    // Today marker
    if (isToday) {
      ctx.strokeStyle = '#6366f1'
      ctx.lineWidth = 1.5
      ctx.setLineDash([3, 3])
      ctx.beginPath()
      ctx.moveTo(x, CHART_PADDING_TOP)
      ctx.lineTo(x, h - CHART_PADDING_BOTTOM)
      ctx.stroke()
      ctx.setLineDash([])
    }

    // Small dot at day label area to indicate transactions exist
    if (hasTxns) {
      ctx.beginPath()
      ctx.arc(x, h - CHART_PADDING_BOTTOM + 2, 1.5, 0, Math.PI * 2)
      ctx.fillStyle = d.net_k > 0 ? '#22c55e' : '#ef4444'
      ctx.fill()
    }
  }

  // --- Balance bars ---
  const barGap = 2
  const barW = DAY_WIDTH - barGap * 2
  const baseY = zeroVisible ? zeroY : h - CHART_PADDING_BOTTOM

  for (let i = firstVisible; i <= lastVisible; i++) {
    const x = xForIndex(i)
    const bucket = days[i]!
    const balY = yForBalance(bucket.balance_k, h)
    const isHov = i === hIdx

    if (bucket.balance_k >= 0) {
      const top = Math.min(balY, baseY)
      const barH = Math.abs(baseY - balY)
      ctx.fillStyle = isHov ? 'rgba(129, 140, 248, 0.55)' : 'rgba(99, 102, 241, 0.35)'
      ctx.fillRect(x - barW / 2, top, barW, barH)
      ctx.strokeStyle = isHov ? '#a5b4fc' : '#818cf8'
      ctx.lineWidth = isHov ? 1.5 : 0.5
      ctx.strokeRect(x - barW / 2, top, barW, barH)
    } else {
      const top = baseY
      const barH = Math.abs(balY - baseY)
      ctx.fillStyle = isHov ? 'rgba(239, 68, 68, 0.55)' : 'rgba(239, 68, 68, 0.35)'
      ctx.fillRect(x - barW / 2, top, barW, barH)
      ctx.strokeStyle = isHov ? '#fca5a5' : '#ef4444'
      ctx.lineWidth = isHov ? 1.5 : 0.5
      ctx.strokeRect(x - barW / 2, top, barW, barH)
    }
  }

  // --- Zero line — solid red, drawn on top of bars ---
  if (zeroVisible) {
    ctx.strokeStyle = '#ef4444'
    ctx.lineWidth = 2
    ctx.setLineDash([])
    ctx.beginPath()
    ctx.moveTo(CHART_PADDING_LEFT, zeroY)
    ctx.lineTo(w, zeroY)
    ctx.stroke()
  }

  // Hovered day Y-axis badge
  if (hIdx !== null && hIdx >= firstVisible && hIdx <= lastVisible) {
    const hBucket = days[hIdx]!
    const hy = yForBalance(hBucket.balance_k, h)

    // Horizontal crosshair
    ctx.strokeStyle = 'rgba(148, 163, 184, 0.2)'
    ctx.lineWidth = 1
    ctx.setLineDash([2, 2])
    ctx.beginPath()
    ctx.moveTo(CHART_PADDING_LEFT, hy)
    ctx.lineTo(w, hy)
    ctx.stroke()
    ctx.setLineDash([])

    // Y-axis label badge
    ctx.fillStyle = '#818cf8'
    ctx.fillRect(0, hy - 10, CHART_PADDING_LEFT - 4, 20)
    ctx.fillStyle = '#fff'
    ctx.font = 'bold 10px "JetBrains Mono", monospace'
    ctx.textAlign = 'right'
    ctx.textBaseline = 'middle'
    ctx.fillText(formatK(hBucket.balance_k), CHART_PADDING_LEFT - 8, hy)
  }

  // Global min markers (triangle)
  for (const minDate of props.globalMinDates) {
    const idx = days.findIndex(d => d.date === minDate)
    if (idx < firstVisible || idx > lastVisible) continue
    const mBucket = days[idx]!
    const mx = xForIndex(idx)
    const my = yForBalance(mBucket.balance_k, h)
    ctx.beginPath()
    ctx.moveTo(mx, my - 8)
    ctx.lineTo(mx - 5, my - 14)
    ctx.lineTo(mx + 5, my - 14)
    ctx.closePath()
    ctx.fillStyle = mBucket.balance_k < 0 ? '#ef4444' : '#f59e0b'
    ctx.fill()
  }
}

function formatK(val: number): string {
  if (Math.abs(val) >= 1000) return (val / 1000).toFixed(1) + 'M'
  return val.toFixed(1) + 'k'
}

function niceGridSteps(min: number, max: number, target: number): number[] {
  const range = max - min
  if (range <= 0) return [0]
  const rough = range / target
  const mag = Math.pow(10, Math.floor(Math.log10(rough)))
  let step = mag
  if (rough / mag >= 5) step = mag * 5
  else if (rough / mag >= 2) step = mag * 2

  const steps: number[] = []
  let v = Math.ceil(min / step) * step
  while (v <= max) {
    steps.push(Math.round(v * 1000) / 1000)
    v += step
  }
  return steps
}

function formatDateForTooltip(iso: string): string {
  const [, mo, dy] = parseDateParts(iso)
  const wd = weekday(iso)
  return (WEEKDAY_NAMES[wd] ?? '') + ', ' + (MONTH_NAMES[parseInt(mo) - 1] ?? '') + ' ' + parseInt(dy)
}

// --- Scroll / pan with momentum ---

function clampScroll() {
  if (!containerRef.value) return
  const maxScroll = Math.max(0, totalWidth.value - containerRef.value.clientWidth)
  scrollX.value = Math.max(0, Math.min(scrollX.value, maxScroll))
}

function centerOnToday() {
  if (!containerRef.value) return
  const todayIdx = props.days.findIndex(d => d.date === today)
  if (todayIdx < 0) return
  const viewW = containerRef.value.clientWidth
  scrollX.value = CHART_PADDING_LEFT + todayIdx * DAY_WIDTH - viewW * 0.37
  clampScroll()
}

function onPointerDown(e: PointerEvent) {
  isDragging.value = true
  dragStartX = e.clientX
  dragStartScroll = scrollX.value
  lastDragX = e.clientX
  lastDragTime = performance.now()
  velocityX = 0
  cancelAnimationFrame(animFrame)
  ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
}

function onPointerMove(e: PointerEvent) {
  const idx = indexForClientX(e.clientX)
  if (!isDragging.value) {
    hoveredIndex.value = idx
    draw()
    return
  }

  const now = performance.now()
  const dt = now - lastDragTime
  const dx = e.clientX - lastDragX
  if (dt > 0) velocityX = dx / dt

  lastDragX = e.clientX
  lastDragTime = now

  scrollX.value = dragStartScroll - (e.clientX - dragStartX)
  clampScroll()
  hoveredIndex.value = idx
  draw()
}

function onPointerUp(e: PointerEvent) {
  if (!isDragging.value) return
  isDragging.value = false
  ;(e.target as HTMLElement).releasePointerCapture(e.pointerId)

  const dist = Math.abs(e.clientX - dragStartX)
  if (dist < 4) {
    const idx = indexForClientX(e.clientX)
    if (idx !== null) {
      selectedIndex.value = idx
      emit('selectDay', props.days[idx]!.date)
    }
    draw()
    return
  }

  if (Math.abs(velocityX) > 0.1) {
    const friction = 0.95
    const tick = () => {
      velocityX *= friction
      scrollX.value -= velocityX * 16
      clampScroll()
      draw()
      if (Math.abs(velocityX) > 0.05) animFrame = requestAnimationFrame(tick)
    }
    animFrame = requestAnimationFrame(tick)
  }
}

function onPointerLeave() {
  if (!isDragging.value) {
    hoveredIndex.value = null
    draw()
  }
}

function onWheel(e: WheelEvent) {
  scrollX.value += e.deltaX || e.deltaY
  clampScroll()
  draw()
}

function onKeyDown(e: KeyboardEvent) {
  const current = selectedIndex.value ?? hoveredIndex.value
  if (e.key === 'ArrowRight') {
    e.preventDefault()
    const next = current !== null ? Math.min(current + 1, props.days.length - 1) : 0
    selectedIndex.value = next
    ensureVisible(next)
    emit('selectDay', props.days[next]!.date)
    draw()
  } else if (e.key === 'ArrowLeft') {
    e.preventDefault()
    const prev = current !== null ? Math.max(current - 1, 0) : 0
    selectedIndex.value = prev
    ensureVisible(prev)
    emit('selectDay', props.days[prev]!.date)
    draw()
  } else if (e.key === 'Enter' && current !== null) {
    emit('selectDay', props.days[current]!.date)
  }
}

function ensureVisible(idx: number) {
  if (!containerRef.value) return
  const x = CHART_PADDING_LEFT + idx * DAY_WIDTH
  const viewW = containerRef.value.clientWidth
  if (x - scrollX.value < CHART_PADDING_LEFT + 20) {
    scrollX.value = x - CHART_PADDING_LEFT - 40
  } else if (x - scrollX.value > viewW - 40) {
    scrollX.value = x - viewW + 60
  }
  clampScroll()
}

let resizeObs: ResizeObserver | null = null

onMounted(() => {
  centerOnToday()
  draw()
  resizeObs = new ResizeObserver(() => draw())
  if (containerRef.value) resizeObs.observe(containerRef.value)
})

onUnmounted(() => {
  cancelAnimationFrame(animFrame)
  resizeObs?.disconnect()
})

watch(
  [() => props.days, () => props.globalMin, () => props.globalMinDates, () => props.firstNegativeDate],
  () => draw(),
)

defineExpose({ centerOnToday })

/*--script--*/

src/components/liquidity/TransactionForm.content:
import { ref, computed, watch } from 'vue'
import type {
  LiquidityTransaction,
  LiquidityRecurringTransaction,
  LiquidityRecurringFrequency,
} from '../../types/liquidity'
import {
  addDays,
  describeRecurrence,
  expandRecurringRule,
  todayISO,
} from '../../utils/liquidityEngine'

/**
 * Unified add/edit modal for both one-off and recurring cash flows.
 *
 * The component owns no persistence — it emits a discriminated `save`
 * payload (`kind: 'transaction' | 'recurring'`) plus an optional `id` and
 * the parent decides which store action to call. This keeps the form
 * trivial to test and lets the parent run pre-save simulation warnings.
 */

const props = defineProps<{
  open: boolean
  editTxn?: LiquidityTransaction | null
  /** Pass the source rule when editing a virtual recurring instance. */
  editRecurring?: LiquidityRecurringTransaction | null
  prefillDate?: string | null
}>()

type SaveOneOff = {
  kind: 'transaction'
  id?: string
  effective_date: string
  description: string
  amount_k: number
}

type SaveRecurring = {
  kind: 'recurring'
  id?: string
  description: string
  amount_k: number
  start_date: string
  end_date: string | null
  occurrences: number | null
  frequency: LiquidityRecurringFrequency
  interval: number
}

const emit = defineEmits<{
  (e: 'close'): void
  (e: 'save', data: SaveOneOff | SaveRecurring): void
}>()

const FREQUENCIES: { value: LiquidityRecurringFrequency; label: string }[] = [
  { value: 'daily', label: 'Daily' },
  { value: 'weekly', label: 'Weekly' },
  { value: 'biweekly', label: 'Biweekly' },
  { value: 'monthly', label: 'Monthly' },
  { value: 'quarterly', label: 'Quarterly' },
  { value: 'yearly', label: 'Yearly' },
]

type EndMode = 'never' | 'on' | 'after'

// ---- form state ------------------------------------------------------------
const isOutflow = ref(true)
const amount = ref('')
const description = ref('')
const effectiveDate = ref(todayISO())

const isRecurring = ref(false)
const startDate = ref(todayISO())
const frequency = ref<LiquidityRecurringFrequency>('monthly')
const interval = ref('1')
const endMode = ref<EndMode>('never')
const endDate = ref(addDays(todayISO(), 365))
const occurrences = ref('12')

// ---- computed --------------------------------------------------------------
const isEditingOneOff = computed(() => !!props.editTxn && !props.editRecurring)
const isEditingRecurring = computed(() => !!props.editRecurring)
const isEditing = computed(() => isEditingOneOff.value || isEditingRecurring.value)

const title = computed(() => {
  if (isEditingRecurring.value) return 'Edit Recurring Flow'
  if (isEditingOneOff.value) return 'Edit Transaction'
  return isRecurring.value ? 'Add Recurring Flow' : 'Add Transaction'
})

// We hide the recurring toggle when editing an existing row to keep the
// "change one-off into recurring" edge case out of v1.
const canToggleRecurring = computed(() => !isEditing.value)

watch(() => props.open, (open) => {
  if (!open) return

  if (props.editRecurring) {
    const r = props.editRecurring
    isRecurring.value = true
    isOutflow.value = r.amount_k < 0
    amount.value = Math.abs(r.amount_k).toString()
    description.value = r.description
    startDate.value = r.start_date
    frequency.value = r.frequency
    interval.value = String(r.interval || 1)
    if (r.occurrences != null) {
      endMode.value = 'after'
      occurrences.value = String(r.occurrences)
    } else if (r.end_date) {
      endMode.value = 'on'
      endDate.value = r.end_date
    } else {
      endMode.value = 'never'
    }
  } else if (props.editTxn) {
    isRecurring.value = false
    isOutflow.value = props.editTxn.amount_k < 0
    amount.value = Math.abs(props.editTxn.amount_k).toString()
    description.value = props.editTxn.description
    effectiveDate.value = props.editTxn.effective_date
  } else {
    isRecurring.value = false
    isOutflow.value = true
    amount.value = ''
    description.value = ''
    effectiveDate.value = props.prefillDate || todayISO()
    startDate.value = props.prefillDate || todayISO()
    frequency.value = 'monthly'
    interval.value = '1'
    endMode.value = 'never'
    endDate.value = addDays(props.prefillDate || todayISO(), 365)
    occurrences.value = '12'
  }
})

const intervalNum = computed(() => {
  const n = parseInt(interval.value, 10)
  return Number.isFinite(n) && n > 0 ? n : 1
})

const occurrencesNum = computed(() => {
  const n = parseInt(occurrences.value, 10)
  return Number.isFinite(n) && n > 0 ? n : null
})

const isValid = computed(() => {
  const a = parseFloat(amount.value)
  if (!(a > 0)) return false
  if (description.value.trim().length === 0) return false

  if (isRecurring.value) {
    if (!startDate.value) return false
    if (endMode.value === 'on' && (!endDate.value || endDate.value < startDate.value)) return false
    if (endMode.value === 'after' && !occurrencesNum.value) return false
    return true
  }

  return effectiveDate.value.length > 0
})

const recurrencePreview = computed(() => {
  if (!isRecurring.value || !isValid.value) return null
  const a = parseFloat(amount.value)
  const signedAmount = isOutflow.value ? -Math.abs(a) : Math.abs(a)
  const virtualRule: LiquidityRecurringTransaction = {
    id: '__preview__',
    description: description.value.trim() || 'Preview',
    amount_k: signedAmount,
    start_date: startDate.value,
    end_date: endMode.value === 'on' ? endDate.value : null,
    occurrences: endMode.value === 'after' ? occurrencesNum.value : null,
    frequency: frequency.value,
    interval: intervalNum.value,
  }
  // Project up to 5 occurrences inside a 5-year window for the preview.
  const previewWindowEnd = addDays(startDate.value, 365 * 5)
  const projected = expandRecurringRule(virtualRule, startDate.value, previewWindowEnd)
  const first5 = projected.slice(0, 5)
  return {
    cadence: describeRecurrence(virtualRule),
    upcoming: first5,
    totalShown: projected.length,
  }
})

function onSave() {
  if (!isValid.value) return
  const a = parseFloat(amount.value)
  const signedAmount = isOutflow.value ? -Math.abs(a) : Math.abs(a)

  if (isRecurring.value) {
    emit('save', {
      kind: 'recurring',
      id: props.editRecurring?.id,
      description: description.value.trim(),
      amount_k: signedAmount,
      start_date: startDate.value,
      end_date: endMode.value === 'on' ? endDate.value : null,
      occurrences: endMode.value === 'after' ? occurrencesNum.value : null,
      frequency: frequency.value,
      interval: intervalNum.value,
    })
    return
  }

  emit('save', {
    kind: 'transaction',
    id: props.editTxn?.id,
    effective_date: effectiveDate.value,
    description: description.value.trim(),
    amount_k: signedAmount,
  })
}

function onKeyDown(e: KeyboardEvent) {
  if (e.key === 'Escape') emit('close')
  if (e.key === 'Enter' && e.metaKey && isValid.value) onSave()
}

function formatPreviewDate(iso: string): string {
  const parts = iso.split('-')
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
  return (months[parseInt(parts[1] ?? '0') - 1] ?? '') + ' ' + parseInt(parts[2] ?? '0') + ', ' + (parts[0] ?? '')
}

/*--script--*/

src/components/reps/RepsEntriesList.vue.content:
import { computed, ref } from 'vue';
import type { RepsEntryRow } from '../../types/reps';

const props = defineProps<{
  entries: RepsEntryRow[];
  loading?: boolean;
  error?: string | null;
}>();

const filterMaterial = ref<'all' | 'material' | 'non-material'>('all');
const filterPerson = ref<string>('');
const search = ref('');

const allPeople = computed(() => {
  const set = new Set<string>();
  for (const e of props.entries) {
    for (const p of e.people_involved || []) set.add(p);
  }
  return Array.from(set).sort();
});

const filtered = computed(() => {
  return props.entries
    .slice()
    .sort((a, b) => (b.start_time || '').localeCompare(a.start_time || ''))
    .filter(e => {
      if (filterMaterial.value === 'material' && !e.material_participation_rentals) return false;
      if (filterMaterial.value === 'non-material' && e.material_participation_rentals) return false;
      if (filterPerson.value && !(e.people_involved || []).includes(filterPerson.value)) return false;
      if (search.value) {
        const q = search.value.toLowerCase();
        const hay = [e.description, e.property_name, e.activity_category, e.location].filter(Boolean).join(' ').toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
});

function fmtDate(iso: string | null) {
  if (!iso) return '—';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return iso;
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
}

function fmtTimeRange(start: string | null, end: string | null) {
  if (!start || !end) return '—';
  try {
    const s = new Date(start);
    const e = new Date(end);
    const fmt = (d: Date) => d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
    return `${fmt(s)} – ${fmt(e)}`;
  } catch {
    return '—';
  }
}

/*--script--*/

src/components/reps/RepsEntryModal.vue.content:
import { computed, ref, watch } from 'vue';
import api from '../../api';
import { useRepsStore, captureGeoSnapshot } from '../../stores/repsStore';
import {
  FALLBACK_REPS_ACTIVITY_CATEGORIES,
  type EvidenceItem,
  type LocationSnapshot,
  type RepsLogPayload,
  type RepsUser,
} from '../../types/reps';

const props = defineProps<{
  open: boolean;
  user: RepsUser;
  // Pre-filled from the timer when "Finish & Log" is clicked.
  initialStartIso?: string | null;
  initialEndIso?: string | null;
  // Min description length pulled from /reps/config-status (defaults to 20).
  minDescriptionLength?: number;
}>();

const emit = defineEmits<{
  (e: 'close'): void;
  (e: 'saved'): void;
}>();

const store = useRepsStore();

const MIN_DESC = computed(() => props.minDescriptionLength ?? 20);

// --- Form state --- //
const propertyName = ref('');
const propertyQuery = ref('');
const showPropertyDropdown = ref(false);
const activityCategory = ref<string>('');
const newCategoryName = ref('');
const addingCategory = ref(false);
const showAddCategory = ref(false);

const description = ref('');
// HTML datetime-local inputs: yyyy-MM-ddTHH:mm
const startLocal = ref('');
const endLocal = ref('');

// Multi-file evidence: any File queued before opening the modal (real-time
// camera shots taken during a session) is merged with files added inside
// the modal here. Each file has a parallel `label` so the user can edit the
// short name shown in the Sheet's evidence cell (defaults to the filename
// without extension).
const localFiles = ref<File[]>([]);
const localLabels = ref<string[]>([]);
const timerLabels = ref<string[]>([]);
const evidenceError = ref('');

function deriveLabel(name: string): string {
  // Strip extension and any trailing audit-style timestamp/index suffix so
  // the user sees a clean default they're likely to keep ("Closing meeting"
  // over "ClosingMeeting_2026-05-03_1200").
  const stem = name.replace(/\.[^./\\]+$/, '');
  return stem.length > 80 ? stem.slice(0, 80) : stem;
}

// Optional manual location override / context (e.g. "Remote", "Property
// site visit"). The actual GPS breadcrumbs come from `pendingSnapshots`
// + a final manual_save snapshot taken when "Save" is clicked.
const locationNote = ref('');
const pendingSnapshots = ref<LocationSnapshot[]>([]);
const capturingSnapshot = ref(false);

const materialParticipation = ref(false);
const peopleSelected = ref<Set<string>>(new Set());
const newPersonName = ref('');

const submitting = ref(false);
const uploadingFiles = ref(false);
const formError = ref('');

const ALLOWED_FILE_EXTS = ['.pdf', '.jpg', '.jpeg', '.png', '.mov', '.mp4'];
const ALLOWED_FILE_ACCEPT = ALLOWED_FILE_EXTS.join(',');

// Files merged from the live timer session + files chosen in the modal.
// Order MUST match `allLabels` so we can zip URLs back to labels on save.
const allFiles = computed<File[]>(() => [
  ...store.inFlightFilesByUser[props.user],
  ...localFiles.value,
]);

const allLabels = computed<string[]>(() => [
  ...timerLabels.value,
  ...localLabels.value,
]);

const allSnapshots = computed<LocationSnapshot[]>(() => [
  ...store.snapshotsByUser[props.user],
  ...pendingSnapshots.value,
]);

function isoToLocal(iso?: string | null): string {
  if (!iso) return '';
  const d = new Date(iso);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function localToIso(local: string): string {
  if (!local) return '';
  return new Date(local).toISOString();
}

function resetForm() {
  propertyName.value = '';
  propertyQuery.value = '';
  showPropertyDropdown.value = false;
  activityCategory.value = '';
  newCategoryName.value = '';
  showAddCategory.value = false;
  description.value = '';
  startLocal.value = '';
  endLocal.value = '';
  localFiles.value = [];
  localLabels.value = [];
  // Seed timer-side labels from whatever the timer captured during clocking.
  timerLabels.value = store.inFlightFilesByUser[props.user].map(f => deriveLabel(f.name));
  evidenceError.value = '';
  locationNote.value = '';
  pendingSnapshots.value = [];
  capturingSnapshot.value = false;
  materialParticipation.value = false;
  peopleSelected.value = new Set();
  newPersonName.value = '';
  submitting.value = false;
  uploadingFiles.value = false;
  formError.value = '';
}

watch(
  () => props.open,
  async (open) => {
    if (!open) return;
    resetForm();
    startLocal.value = isoToLocal(props.initialStartIso) || isoToLocal(new Date().toISOString());
    endLocal.value = isoToLocal(props.initialEndIso) || isoToLocal(new Date().toISOString());
    if (store.properties.length === 0) {
      try { await store.fetchProperties(); } catch (err) { console.warn(err); }
    }
    if (store.people.length === 0) {
      try { await store.fetchPeople(); } catch (err) { console.warn(err); }
    }
    if (store.activityCategories.length === 0) {
      try { await store.fetchActivityCategories(); } catch (err) { console.warn(err); }
    }
  },
  { immediate: true },
);

const filteredProperties = computed(() => {
  const q = propertyQuery.value.trim().toLowerCase();
  if (!q) return store.properties;
  return store.properties.filter(p => p.name.toLowerCase().includes(q));
});

const isExactMatch = computed(() => {
  const q = propertyQuery.value.trim().toLowerCase();
  if (!q) return true;
  return store.properties.some(p => p.name.toLowerCase() === q);
});

function pickProperty(name: string) {
  propertyName.value = name;
  propertyQuery.value = name;
  showPropertyDropdown.value = false;
}

function onPropertyBlur() {
  window.setTimeout(() => { showPropertyDropdown.value = false; }, 150);
}

const totalHours = computed(() => {
  if (!startLocal.value || !endLocal.value) return 0;
  const start = new Date(startLocal.value).getTime();
  const end = new Date(endLocal.value).getTime();
  if (!isFinite(start) || !isFinite(end) || end <= start) return 0;
  return Math.round(((end - start) / 3_600_000) * 100) / 100;
});

const descRemaining = computed(() => Math.max(0, MIN_DESC.value - description.value.trim().length));
const descTooShort = computed(() => description.value.trim().length < MIN_DESC.value);

// Categories shown in the dropdown — server-backed when available, fallback list otherwise.
const categoryOptions = computed<string[]>(() => {
  if (store.activityCategories.length > 0) {
    return store.activityCategories.map(c => c.name);
  }
  return [...FALLBACK_REPS_ACTIVITY_CATEGORIES];
});

// --- File handling --- //

function validateAndAcceptFiles(files: FileList | File[] | null) {
  evidenceError.value = '';
  if (!files) return;
  const accepted: File[] = [];
  for (const f of Array.from(files)) {
    const ext = ('.' + f.name.split('.').pop()!).toLowerCase();
    if (!ALLOWED_FILE_EXTS.includes(ext)) {
      evidenceError.value = `Skipped "${f.name}" — only ${ALLOWED_FILE_EXTS.join(', ')} allowed.`;
      continue;
    }
    accepted.push(f);
  }
  if (accepted.length > 0) {
    localFiles.value = [...localFiles.value, ...accepted];
    localLabels.value = [...localLabels.value, ...accepted.map(f => deriveLabel(f.name))];
  }
}

function onFileInputChange(e: Event) {
  const input = e.target as HTMLInputElement;
  validateAndAcceptFiles(input.files);
  input.value = '';
}

function removeFileFromLocal(idx: number) {
  const files = [...localFiles.value];
  const labels = [...localLabels.value];
  files.splice(idx, 1);
  labels.splice(idx, 1);
  localFiles.value = files;
  localLabels.value = labels;
}

function removeFileFromTimer(idx: number) {
  // Keep `timerLabels` in lock-step with the store's queue so the zip on
  // save still maps each label to the right uploaded URL.
  const labels = [...timerLabels.value];
  labels.splice(idx, 1);
  timerLabels.value = labels;
  store.removeInFlightFile(props.user, idx);
}

const cameraInputRef = ref<HTMLInputElement | null>(null);

function openCameraDirect() {
  cameraInputRef.value?.click();
}

// --- People handling --- //

function togglePerson(name: string) {
  const s = new Set(peopleSelected.value);
  if (s.has(name)) s.delete(name);
  else s.add(name);
  peopleSelected.value = s;
}

async function quickAddPerson() {
  const name = newPersonName.value.trim();
  if (!name) return;
  try {
    await store.addPerson({ name });
    togglePerson(name);
    newPersonName.value = '';
  } catch (err: any) {
    formError.value = err?.response?.data?.detail || 'Failed to add person';
  }
}

// --- Activity-category quick add --- //

async function addCategoryInline() {
  const name = newCategoryName.value.trim();
  if (!name) return;
  addingCategory.value = true;
  try {
    const cat = await store.addActivityCategory(name);
    if (cat) activityCategory.value = cat.name;
    newCategoryName.value = '';
    showAddCategory.value = false;
  } catch (err: any) {
    formError.value = err?.response?.data?.detail || 'Failed to add category';
  } finally {
    addingCategory.value = false;
  }
}

// --- Geolocation --- //

async function captureSnapshotNow(kind: LocationSnapshot['kind'] = 'manual_save') {
  capturingSnapshot.value = true;
  try {
    const snap = await captureGeoSnapshot(kind);
    pendingSnapshots.value = [...pendingSnapshots.value, snap];
  } finally {
    capturingSnapshot.value = false;
  }
}

function markRemote() {
  pendingSnapshots.value = [
    ...pendingSnapshots.value,
    {
      kind: 'manual_save',
      captured_at: new Date().toISOString(),
      note: locationNote.value.trim() || 'Remote',
    },
  ];
}

function dropPendingSnapshot(idx: number) {
  const list = [...pendingSnapshots.value];
  list.splice(idx, 1);
  pendingSnapshots.value = list;
}

function snapshotLabel(s: LocationSnapshot): string {
  const KIND_LABEL: Record<string, string> = {
    manual_save: 'MANUAL',
    timer_start: 'START',
    timer_pause: 'PAUSE',
    timer_resume: 'RESUME',
    timer_stop: 'STOP',
    bookmark: 'BOOKMARK',
    evidence_capture: 'PHOTO',
  };
  return KIND_LABEL[s.kind] || s.kind.toUpperCase();
}

function snapshotMapHref(s: LocationSnapshot): string | null {
  if (s.lat == null || s.lng == null) return null;
  return `https://maps.google.com/?q=${s.lat.toFixed(5)},${s.lng.toFixed(5)}`;
}

// --- Save --- //

async function save() {
  formError.value = '';

  if (!startLocal.value || !endLocal.value) {
    formError.value = 'Start and end times are required.';
    return;
  }
  if (new Date(endLocal.value).getTime() <= new Date(startLocal.value).getTime()) {
    formError.value = 'End time must be after start time.';
    return;
  }
  if (descTooShort.value) {
    formError.value = `Description must be at least ${MIN_DESC.value} characters (be specific!).`;
    return;
  }

  const finalProperty = (propertyName.value || propertyQuery.value).trim();
  if (finalProperty && !isExactMatch.value) {
    try { await store.ensureProspect(finalProperty); }
    catch (err) { console.warn('Failed to save prospect:', err); }
  }

  // Note: GPS snapshots are captured ONLY when the user explicitly clicks
  // "Capture GPS now" in the modal or "Pin GPS now" on the timer. Save no
  // longer auto-snaps — the audit trail reflects what the user chose to log.

  // Step 1: upload all queued files (no per-log folder anymore — they land
  // flat in the property's GCS directory), then zip the returned URLs back
  // to the user-supplied labels in input-order.
  let evidenceItems: EvidenceItem[] = [];
  if (allFiles.value.length > 0) {
    uploadingFiles.value = true;
    try {
      const batch = await api.uploadRepsEvidenceBatch({
        user: props.user,
        files: allFiles.value,
        propertyName: finalProperty || null,
        activityCategory: activityCategory.value || null,
        logTimestamp: new Date().toISOString(),
      });
      const labels = allLabels.value;
      evidenceItems = batch.files.map((f, i) => ({
        url: f.url,
        label: (labels[i] || '').trim() || deriveLabel(f.name),
      }));
    } catch (err: any) {
      uploadingFiles.value = false;
      formError.value = err?.response?.data?.detail || 'Failed to upload evidence';
      return;
    } finally {
      uploadingFiles.value = false;
    }
  }

  const payload: RepsLogPayload = {
    user: props.user,
    property_name: finalProperty || null,
    activity_category: activityCategory.value || null,
    description: description.value.trim(),
    start_time: localToIso(startLocal.value),
    end_time: localToIso(endLocal.value),
    evidence_items: evidenceItems,
    location_snapshots: allSnapshots.value,
    location: locationNote.value.trim() || null,
    material_participation_rentals: materialParticipation.value,
    people_involved: Array.from(peopleSelected.value),
  };

  // Step 2: append the row.
  submitting.value = true;
  try {
    await api.logRepsEntry(payload);
    await store.fetchEntries(props.user);
    emit('saved');
    emit('close');
  } catch (err: any) {
    formError.value = err?.response?.data?.detail || err?.message || 'Failed to save entry';
  } finally {
    submitting.value = false;
  }
}

function close() {
  if (submitting.value || uploadingFiles.value) return;
  emit('close');
}

/*--script--*/

src/components/reps/RepsPeopleManager.vu.content:
import { ref } from 'vue';
import { useRepsStore } from '../../stores/repsStore';

const store = useRepsStore();

const newName = ref('');
const newRole = ref('');
const newNotes = ref('');
const editingId = ref<string | null>(null);
const editName = ref('');
const editRole = ref('');
const editNotes = ref('');
const error = ref('');

async function add() {
  error.value = '';
  if (!newName.value.trim()) return;
  try {
    await store.addPerson({
      name: newName.value.trim(),
      role: newRole.value.trim() || undefined,
      notes: newNotes.value.trim() || undefined,
    });
    newName.value = '';
    newRole.value = '';
    newNotes.value = '';
  } catch (err: any) {
    error.value = err?.response?.data?.detail || 'Failed to add';
  }
}

function startEdit(p: { id: string; name: string; role?: string | null; notes?: string | null }) {
  editingId.value = p.id;
  editName.value = p.name;
  editRole.value = p.role || '';
  editNotes.value = p.notes || '';
}

async function saveEdit() {
  if (!editingId.value) return;
  error.value = '';
  try {
    await store.updatePerson(editingId.value, {
      name: editName.value.trim(),
      role: editRole.value.trim() || undefined,
      notes: editNotes.value.trim() || undefined,
    });
    editingId.value = null;
  } catch (err: any) {
    error.value = err?.response?.data?.detail || 'Failed to update';
  }
}

async function remove(id: string) {
  if (!confirm('Delete this person? Existing log entries will keep the name.')) return;
  try {
    await store.removePerson(id);
  } catch (err: any) {
    error.value = err?.response?.data?.detail || 'Failed to delete';
  }
}

/*--script--*/

