src/components/reps/RepsTimer.vue.content:
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { useRepsStore } from '../../stores/repsStore';
import type { RepsUser } from '../../types/reps';

const props = defineProps<{
  user: RepsUser;
}>();

const emit = defineEmits<{
  (e: 'finish', payload: { startIso: string; endIso: string; totalHours: number }): void;
}>();

const store = useRepsStore();

// Re-render every second so the on-screen elapsed counter ticks even when the
// store state hasn't changed (it only changes on start/stop).
const tick = ref(Date.now());
let intervalId: ReturnType<typeof setInterval> | null = null;

onMounted(() => {
  intervalId = setInterval(() => {
    tick.value = Date.now();
  }, 1000);
});
onBeforeUnmount(() => {
  if (intervalId) clearInterval(intervalId);
});

const timer = computed(() => store.timers[props.user]);
const isRunning = computed(() => timer.value.running);
const hasSession = computed(() => !!timer.value.sessionStartedAt || timer.value.accumulatedMs > 0 || isRunning.value);

const elapsedMs = computed(() => store.elapsedMs(props.user, tick.value));

const display = computed(() => {
  const totalSec = Math.floor(elapsedMs.value / 1000);
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;
  return [h, m, s].map(n => String(n).padStart(2, '0')).join(':');
});

const decimalHours = computed(() => Math.round((elapsedMs.value / 3_600_000) * 100) / 100);

// Per-user buffers exposed by the store. Reading them through the store keeps
// reactivity intact when switching tabs.
const snapshots = computed(() => store.snapshotsByUser[props.user]);
const inFlightFiles = computed(() => store.inFlightFilesByUser[props.user]);

const lastSnapshot = computed(() => snapshots.value[snapshots.value.length - 1]);
const capturing = ref(false);
const cameraInput = ref<HTMLInputElement | null>(null);
const galleryInput = ref<HTMLInputElement | null>(null);

function start() {
  store.startTimer(props.user);
}

function stop() {
  // Stop pauses the segment but keeps sessionStartedAt + accumulated so the
  // user can resume or finalize. The user may now click "Pin GPS" to record
  // a pause-time location if they want one.
  store.stopTimer(props.user);
}

function resume() {
  store.resumeTimer(props.user);
}

async function pinGps(kind: 'bookmark' | 'timer_pause' | 'timer_resume' | 'timer_stop' | 'timer_start' = 'bookmark') {
  // The single, explicit "capture-my-current-location" button. The `kind`
  // parameter just labels the breadcrumb in the audit trail; we default to
  // a generic `bookmark` so a single tap does the right thing in any state.
  capturing.value = true;
  try {
    await store.captureAndPushSnapshot(props.user, kind);
  } finally {
    capturing.value = false;
  }
}

function finish() {
  if (timer.value.running) {
    store.stopTimer(props.user);
  }
  const start = timer.value.sessionStartedAt;
  const end = new Date().toISOString();
  if (!start) return;
  const totalHours = Math.round((timer.value.accumulatedMs / 3_600_000) * 100) / 100;
  emit('finish', { startIso: start, endIso: end, totalHours });
}

function discard() {
  if (!confirm('Discard this stopwatch session? Timer, GPS breadcrumbs, and queued evidence will reset.')) return;
  store.resetTimer(props.user);
}

// --- Real-time camera / file capture during an active session --- //

function openCamera() {
  cameraInput.value?.click();
}

function openGallery() {
  galleryInput.value?.click();
}

function onCameraFiles(e: Event) {
  const input = e.target as HTMLInputElement;
  const files = Array.from(input.files || []);
  for (const f of files) {
    store.addInFlightFile(props.user, f);
  }
  input.value = '';
}

/*--script--*/

src/components/ui/DaysUntilRefiField.vue.content:
/**
 * "Days until Refi" — the hold between purchase closing and refi closing.
 *
 * Two ways in, one value out. The field's value is always a whole day count
 * (what the backend stores and accrues HML interest against, per diem on a
 * 360-day year); the calendar is purely an easier way to arrive at that number,
 * the way a flight search takes two dates and shows you a trip length.
 *
 * The dates themselves are deliberately *not* stored — only the day count they
 * produce. Picking dates again later is one click, and it keeps the deal record
 * honest about what actually feeds the calculation.
 *
 * Native `<input type="date">` rather than PrimeVue's `DatePicker`: PrimeVue is
 * configured `unstyled: true` with no preset (`main.ts`), so a `DatePicker`
 * would arrive with no styling at all and need its entire panel/header/grid
 * hand-written in `pt`. The native control brings the OS calendar popover and
 * takes our Tailwind classes directly.
 */
import { computed, ref } from "vue";
import NumberInput from "./NumberInput.vue";

defineProps<{
  modelValue: number | null;
  label: string;
  required?: boolean;
}>();

const emit = defineEmits(["update:modelValue"]);

const picking = ref(false);
const purchaseDate = ref("");
const refiDate = ref("");

const MS_PER_DAY = 86_400_000;

/** Whole days between the two dates, or `null` until both are valid. */
const pickedDays = computed<number | null>(() => {
  if (!purchaseDate.value || !refiDate.value) return null;
  const from = Date.parse(`${purchaseDate.value}T00:00:00`);
  const to = Date.parse(`${refiDate.value}T00:00:00`);
  if (Number.isNaN(from) || Number.isNaN(to)) return null;
  const days = Math.round((to - from) / MS_PER_DAY);
  return days > 0 ? days : null;
});

/** Why `Done` is unavailable, if it is. Doubles as the inline error text. */
const pickerProblem = computed(() => {
  if (!purchaseDate.value || !refiDate.value) return "";
  return pickedDays.value == null ? "Refi date must be after the purchase date." : "";
});

const openPicker = () => {
  // Start blank each time — the dates aren't persisted, so any previous pair
  // would just be a stale guess at what produced the current day count.
  purchaseDate.value = "";
  refiDate.value = "";
  picking.value = true;
};

const applyPickedDates = () => {
  if (pickedDays.value == null) return;
  emit("update:modelValue", pickedDays.value);
  picking.value = false;
};

const dateInputClass =
  "w-full bg-white border border-gray-300 rounded-lg px-3 py-2 text-gray-900 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all hover:bg-gray-50";

/*--script--*/

src/components/ui/MoneyInput.vue.content:
/**
 * A money field that shows real dollars.
 *
 * Two things make this a plain `<input type="text">` rather than PrimeVue's
 * `InputNumber`:
 *
 * 1. `InputNumber` cannot express the `k` / `m` shorthand (see `utils/money`).
 * 2. Its live currency mask re-formats on every keystroke and drags the caret
 *    to the end, which is what made the old fields so unpleasant to edit.
 *
 * So: while focused the input holds plain digits the user fully controls, and
 * the formatted `$50,500` is rendered only once they leave. The value commits
 * on blur / Enter — the same commit point the previous `InputNumber` used, so
 * the card modals' debounced autosave and re-analyze behave exactly as before.
 */
import { computed, ref, watch } from "vue";
import { formatMoney, parseMoney, toEditableText } from "../../utils/money";

const props = defineProps<{
  /** In *thousands* when `inThousands`, otherwise in dollars. */
  modelValue: number | null;
  label: string;
  placeholder?: string;
  min?: number;
  max?: number;
  required?: boolean;
  disabled?: boolean;
  /**
   * The value is stored in thousands: display it ×1000, emit ÷1000, and turn
   * on the "a bare number under 1,000 means thousands" typing shortcut.
   */
  inThousands?: boolean;
}>();

const emit = defineEmits(["update:modelValue"]);

const focused = ref(false);
/** What the user is typing. Only authoritative while focused. */
const draft = ref("");

/** The bound value expressed in dollars, whatever unit it is stored in. */
const dollars = computed(() =>
  props.modelValue == null
    ? null
    : props.inThousands
      ? props.modelValue * 1000
      : props.modelValue,
);

/** Re-seed the draft when the value changes underneath us (deal switched). */
watch(dollars, (next) => {
  if (!focused.value) draft.value = toEditableText(next);
});

const displayText = computed(() =>
  focused.value ? draft.value : formatMoney(dollars.value),
);

/** Live interpretation of the draft, shown as a hint while typing. */
const parsed = computed(() =>
  parseMoney(draft.value, props.inThousands === true),
);

/**
 * Show the hint only when the reading isn't self-evident — i.e. when a `k`/`m`
 * suffix or the <1000 rule scaled what they typed. Echoing "= $50,500" back at
 * someone who literally typed 50500 is just noise.
 */
const hint = computed(() =>
  focused.value && parsed.value.scaled && parsed.value.dollars != null
    ? `= ${formatMoney(parsed.value.dollars)}`
    : "",
);

const onFocus = (e: FocusEvent) => {
  draft.value = toEditableText(dollars.value);
  focused.value = true;
  // Select everything so typing replaces the old number, which is what you
  // want ~always on a field like this.
  (e.target as HTMLInputElement).select();
};

/** Parse, clamp, and write back — then let the formatted view take over. */
const commit = () => {
  focused.value = false;
  const { dollars: parsedDollars } = parseMoney(
    draft.value,
    props.inThousands === true,
  );
  if (parsedDollars == null) {
    emit("update:modelValue", null);
    return;
  }
  let next = props.inThousands ? parsedDollars / 1000 : parsedDollars;
  if (props.min != null) next = Math.max(props.min, next);
  if (props.max != null) next = Math.min(props.max, next);
  emit("update:modelValue", next);
};

const onKeydown = (e: KeyboardEvent) => {
  if (e.key === "Enter") {
    (e.target as HTMLInputElement).blur();
  } else if (e.key === "Escape") {
    // Abandon the edit and restore what was there.
    draft.value = toEditableText(dollars.value);
    (e.target as HTMLInputElement).blur();
  }
};

/*--script--*/

src/components/ui/NumberInput.vue.content:
/**
 * A labelled numeric field (percentages, points, counts).
 *
 * Two deliberate details, both fixes for fields that used to fight the user:
 *
 * - **One emit path.** This used to bind `v-model` *and* listen to `@input`,
 *   so every keystroke wrote twice at different points in PrimeVue's lifecycle;
 *   the parent's write-back then re-formatted the input and threw the caret to
 *   the end. Now the value flows in through `:model-value` and out through
 *   `@input` only.
 * - **No fraction mask.** `minFractionDigits` used to become 2 whenever a
 *   sub-1 `step` was passed, so a rate rendered as `6.50` and deleting a single
 *   digit was near-impossible. It is pinned to 0: type as many or as few
 *   decimals as you like.
 */
import InputNumber from "primevue/inputnumber";

defineProps<{
  modelValue: number | null;
  /** Omit to render the input bare, when the caller supplies its own label. */
  label?: string;
  suffix?: string;
  placeholder?: string;
  min?: number;
  max?: number;
  step?: number;
  required?: boolean;
}>();

const emit = defineEmits(["update:modelValue"]);

const handleKeydown = (e: KeyboardEvent) => {
  // Allow Cmd+A / Ctrl+A to select all
  if ((e.metaKey || e.ctrlKey) && e.key === "a") {
    e.preventDefault();
    const input = e.target as HTMLInputElement;
    if (input && typeof input.select === "function") {
      input.select();
    }
  }
};

/*--script--*/

src/components/ui/SliderField.vue.content:
/**
 * A number box paired with a slider (LTV, long-term interest rate).
 *
 * Three deliberate details:
 *
 * - **One emit path**, for the same reason as `NumberInput` — binding `v-model`
 *   *and* `@input` wrote twice per keystroke and made the caret jump.
 * - **The slider's range is not the input's range.** `sliderMin`/`sliderMax`
 *   bound where the thumb can travel, so it can cover the realistic span
 *   (3-12% for a DSCR rate) and stay precise under the mouse, while `min`/`max`
 *   let the typed box accept anything sensible. Previously they were the same,
 *   so typing `65` into a rate box capped at 20 silently became `20`.
 *   Out-of-range values are reported by `validateDealInputs`, not rewritten.
 * - **No fraction mask** (`minFractionDigits: 0`), so `7` doesn't render as
 *   `7.00` and eat your backspaces.
 */
import InputNumber from "primevue/inputnumber";
import Slider from "primevue/slider";
import { computed } from "vue";

const props = defineProps<{
  modelValue: number | null;
  label: string;
  /** Bounds for the typed box. */
  min: number;
  max: number;
  /** Bounds for the slider thumb. Defaults to `min`/`max`. */
  sliderMin?: number;
  sliderMax?: number;
  step?: number;
  suffix?: string;
  required?: boolean;
}>();

const emit = defineEmits(["update:modelValue"]);

const thumbMin = computed(() => props.sliderMin ?? props.min);
const thumbMax = computed(() => props.sliderMax ?? props.max);

/**
 * The slider always needs a concrete position, so an empty field parks the
 * thumb at the low end. The *number box* keeps the real `null` — that is what
 * lets you clear it and retype instead of the value snapping back.
 */
const sliderValue = computed({
  get: () => props.modelValue ?? thumbMin.value,
  set: (val: number) => emit("update:modelValue", val),
});

/*--script--*/

